c.cpp:
class Solution {
public:
    int countDigitAppearances(vector<int>& nums, int digit) {
        int ans = 0;
        for (int x : nums)
            while (x) { ans += (x % 10 == digit); x /= 10; }
        return ans;
    }
};

c.java:
class Solution {
    public int countDigitAppearances(int[] nums, int digit) {
        int ans = 0;
        for (int x : nums)
            while (x > 0) { if (x % 10 == digit) ans++; x /= 10; }
        return ans;
    }
}

c.javascript:
var countDigitAppearances = function(nums, digit) {
    let ans = 0;
    for (let x of nums)
        while (x > 0) { if (x % 10 === digit) ans++; x = Math.floor(x / 10); }
    return ans;
};
